-- Chỉ dùng trên database demo. Các trạng thái lịch sử được dựng sẵn, không mô phỏng giao dịch kho.
-- Đổi mã của dữ liệu demo đã tạo trước đây, giữ nguyên ID, trạng thái và liên kết.
DO $$
DECLARE t text; col text; old_code text; new_code text; prefix text; kind text; old_status text; number text;
BEGIN
 FOR t,col,kind IN SELECT * FROM (VALUES ('material_issues','issue_code','NVL'),('staff_material_returns','code','TRA'),('staff_material_waste','code','HH'),('finished_goods_issues','code','TP'),('finished_goods_defects','code','LOI')) AS x(t,c,k) LOOP
  FOREACH prefix IN ARRAY ARRAY['BEP','PHA'] LOOP
   FOR old_status,number IN SELECT * FROM (VALUES ('PENDING','001'),('APPROVED','002'),('REJECTED','003')) AS x(s,n) LOOP
    old_code := 'DEMO-'||prefix||'-'||kind||'-'||old_status;
    new_code := 'DEMO-'||prefix||'-'||kind||'-'||number;
    EXECUTE format('UPDATE %I SET %I=$1 WHERE %I=$2 AND NOT EXISTS (SELECT 1 FROM %I WHERE %I=$1)',t,col,col,t,col) USING new_code,old_code;
   END LOOP;
  END LOOP;
 END LOOP;
END $$;
INSERT INTO materials (code,name,min_stock,unit_id,category_id)
SELECT v.code,v.name,2,u.id,c.id FROM (VALUES ('DEMO-TRA','Trà lài','kg','Trà'),('DEMO-SUA','Sữa tươi','lít','Sữa'),('DEMO-DUONG','Đường','kg','Gia vị')) v(code,name,unit,category) JOIN units u ON u.name=v.unit JOIN categories c ON c.name=v.category AND c.category_type='MATERIAL' ON CONFLICT (code) DO NOTHING;
-- Chỉ sửa cách gán cũ của dữ liệu demo; phiếu lịch sử giữ đơn vị đã ghi.
UPDATE materials m SET unit_id=u.id, category_id=c.id FROM (VALUES ('DEMO-TRA','kg','Trà'),('DEMO-SUA','lít','Sữa'),('DEMO-DUONG','kg','Gia vị')) v(code,unit,category) JOIN units u ON u.name=v.unit JOIN categories c ON c.name=v.category AND c.category_type='MATERIAL' WHERE m.code=v.code AND m.category_id=(SELECT id FROM categories WHERE name='Thịt' AND category_type='MATERIAL');
UPDATE bom_details d SET unit_id=m.unit_id FROM boms b, materials m WHERE d.bom_id=b.id AND d.material_id=m.id AND b.code='DEMO-BOM-DRINK01' AND m.code='DEMO-SUA' AND d.unit_id=(SELECT id FROM units WHERE name='kg');
INSERT INTO material_lots (material_id,lot_code,expiry_date) SELECT m.id,'LO-'||m.code,'2027-12-31' FROM materials m WHERE m.code IN ('DEMO-TRA','DEMO-SUA','DEMO-DUONG') ON CONFLICT (material_id,lot_code) DO NOTHING;
INSERT INTO material_balances (location_id,material_lot_id,quantity) SELECT w.id,l.id,20 FROM material_lots l JOIN materials m ON m.id=l.material_id CROSS JOIN warehouse_locations w JOIN branches b ON b.id=w.branch_id WHERE b.code='TEST-CN01' AND w.name='Kho lạnh' AND m.code IN ('DEMO-TRA','DEMO-SUA','DEMO-DUONG') ON CONFLICT (location_id,material_lot_id) DO NOTHING;
INSERT INTO products (code,name,category,price,unit,updated_at) VALUES ('DEMO-DRINK01','Trà sữa lài','Đồ uống',35000,'ly',now()),('DEMO-DRINK02','Trà lài','Đồ uống',25000,'ly',now()) ON CONFLICT (code) DO NOTHING;
INSERT INTO boms (code,product_code,version,output_quantity) VALUES ('DEMO-BOM-DRINK01','DEMO-DRINK01',1,1),('DEMO-BOM-DRINK02','DEMO-DRINK02',1,1) ON CONFLICT (code) DO NOTHING;
INSERT INTO bom_details (bom_id,material_id,unit_id,quantity) SELECT b.id,m.id,m.unit_id,v.quantity FROM (VALUES ('DEMO-BOM-DRINK01','DEMO-TRA',0.02::numeric),('DEMO-BOM-DRINK01','DEMO-SUA',0.1),('DEMO-BOM-DRINK01','DEMO-DUONG',0.02),('DEMO-BOM-DRINK02','DEMO-TRA',0.02),('DEMO-BOM-DRINK02','DEMO-DUONG',0.01)) v(bom,material,quantity) JOIN boms b ON b.code=v.bom JOIN materials m ON m.code=v.material ON CONFLICT (bom_id,material_id) DO NOTHING;
INSERT INTO finished_goods_balances (product_code,location_id,quantity) SELECT v.code,w.id,15 FROM (VALUES ('DEMO-DRINK01'),('DEMO-DRINK02')) v(code) CROSS JOIN warehouse_locations w JOIN branches b ON b.id=w.branch_id WHERE b.code='TEST-CN01' AND w.name='Kho lạnh' ON CONFLICT (product_code,location_id) DO NOTHING;
-- Ca đang mở, không tạo thêm khi tài khoản đã có ca.
INSERT INTO staff_shifts (id,user_id,started_at) SELECT gen_random_uuid(),u.id,now()-interval '2 hours' FROM staff_users u WHERE u.code IN ('DEMO-KITCHEN','DEMO-BARISTA','DEMO-CASHIER') AND NOT EXISTS (SELECT 1 FROM staff_shifts s WHERE s.user_id=u.id AND s.ended_at IS NULL);
-- Mỗi vai trò có lệnh chờ cấp, sẵn sàng bắt đầu, đang làm, chờ duyệt và hoàn thành.
INSERT INTO production_orders (code,bom_id,branch_id,production_mode,quantity,status,material_status,assigned_employee_code,note)
SELECT 'DEMO-'||v.prefix||'-LSX-'||v.n,b.id,br.id,'MAKE_TO_STOCK',5,v.status,v.material,v.actor,'Trạng thái lịch sử giả lập; không ghi giao dịch cấp kho.' FROM (VALUES
 ('BEP',1,'DEMO-BOM01','DEMO-KITCHEN','PENDING','UNCHECKED'),('BEP',2,'DEMO-BOM01','DEMO-KITCHEN','PENDING','ISSUED'),('BEP',3,'DEMO-BOM01','DEMO-KITCHEN','IN_PROGRESS','ISSUED'),('BEP',4,'DEMO-BOM01','DEMO-KITCHEN','WAITING_APPROVAL','ISSUED'),('BEP',5,'DEMO-BOM01','DEMO-KITCHEN','COMPLETED','ISSUED'),
 ('PHA',1,'DEMO-BOM-DRINK01','DEMO-BARISTA','PENDING','UNCHECKED'),('PHA',2,'DEMO-BOM-DRINK01','DEMO-BARISTA','PENDING','ISSUED'),('PHA',3,'DEMO-BOM-DRINK01','DEMO-BARISTA','IN_PROGRESS','ISSUED'),('PHA',4,'DEMO-BOM-DRINK01','DEMO-BARISTA','WAITING_APPROVAL','ISSUED'),('PHA',5,'DEMO-BOM-DRINK01','DEMO-BARISTA','COMPLETED','ISSUED')) v(prefix,n,bom,actor,status,material) JOIN boms b ON b.code=v.bom CROSS JOIN branches br WHERE br.code='TEST-CN01' ON CONFLICT (code) DO NOTHING;
INSERT INTO finished_goods_receipts (code,production_order_id,reported_quantity,accepted_quantity,status,created_at) SELECT 'DEMO-NTP-'||v.prefix||'-'||v.n,o.id,5,CASE WHEN v.n=5 THEN 5 ELSE NULL END,CASE WHEN v.n=5 THEN 'APPROVED' ELSE 'PENDING' END,now() FROM (VALUES ('BEP',4),('BEP',5),('PHA',4),('PHA',5)) v(prefix,n) JOIN production_orders o ON o.code='DEMO-'||v.prefix||'-LSX-'||v.n ON CONFLICT (code) DO NOTHING;
-- Phiếu xuất NVL đủ ba trạng thái, có liên kết tài khoản để xem lịch sử và thử hoàn trả.
INSERT INTO material_issues (issue_code,branch_id,status,note) SELECT 'DEMO-'||v.prefix||'-NVL-'||(CASE v.status WHEN 'PENDING' THEN '001' WHEN 'APPROVED' THEN '002' ELSE '003' END),b.id,v.status,'Lịch sử mẫu' FROM (VALUES ('BEP','PENDING'),('BEP','APPROVED'),('BEP','REJECTED'),('PHA','PENDING'),('PHA','APPROVED'),('PHA','REJECTED')) v(prefix,status) CROSS JOIN branches b WHERE b.code='TEST-CN01' ON CONFLICT (issue_code) DO NOTHING;
INSERT INTO material_issue_details (issue_id,material_id,material_lot_id,location_id,unit_id,quantity) SELECT i.id,m.id,l.id,w.id,m.unit_id,5 FROM material_issues i JOIN branches b ON b.id=i.branch_id JOIN warehouse_locations w ON w.branch_id=b.id AND w.name='Kho lạnh' JOIN materials m ON m.code=CASE WHEN i.issue_code LIKE 'DEMO-BEP-%' THEN 'TEST-NVL001' ELSE 'DEMO-TRA' END JOIN material_lots l ON l.material_id=m.id WHERE i.issue_code LIKE 'DEMO-%-NVL-%' AND NOT EXISTS (SELECT 1 FROM material_issue_details d WHERE d.issue_id=i.id);
INSERT INTO staff_audits (id,actor_id,action,target_id,detail) SELECT gen_random_uuid(),u.id,'MATERIAL_REQUEST',i.id::text,i.issue_code FROM material_issues i JOIN staff_users u ON u.code=CASE WHEN i.issue_code LIKE 'DEMO-BEP-%' THEN 'DEMO-KITCHEN' ELSE 'DEMO-BARISTA' END WHERE i.issue_code LIKE 'DEMO-%-NVL-%' AND NOT EXISTS (SELECT 1 FROM staff_audits a WHERE a.actor_id=u.id AND a.action='MATERIAL_REQUEST' AND a.target_id=i.id::text);
INSERT INTO staff_material_returns (id,code,actor_id,branch_id,issue_detail_id,quantity,note,status) SELECT gen_random_uuid(),'DEMO-'||v.prefix||'-TRA-'||(CASE v.status WHEN 'PENDING' THEN '001' WHEN 'APPROVED' THEN '002' ELSE '003' END),u.id,i.branch_id,d.id,0.5,'Lịch sử mẫu',v.status FROM (VALUES ('BEP','DEMO-KITCHEN','PENDING'),('BEP','DEMO-KITCHEN','APPROVED'),('BEP','DEMO-KITCHEN','REJECTED'),('PHA','DEMO-BARISTA','PENDING'),('PHA','DEMO-BARISTA','APPROVED'),('PHA','DEMO-BARISTA','REJECTED')) v(prefix,actor,status) JOIN staff_users u ON u.code=v.actor JOIN material_issues i ON i.issue_code='DEMO-'||v.prefix||'-NVL-002' JOIN material_issue_details d ON d.issue_id=i.id ON CONFLICT (code) DO NOTHING;
INSERT INTO staff_material_waste (id,code,actor_id,branch_id,balance_id,quantity,reason,status) SELECT gen_random_uuid(),'DEMO-'||v.prefix||'-HH-'||(CASE v.status WHEN 'PENDING' THEN '001' WHEN 'APPROVED' THEN '002' ELSE '003' END),u.id,u.branch_id,mb.id,0.5,'Lịch sử mẫu: nguyên liệu hỏng',v.status FROM (VALUES ('BEP','DEMO-KITCHEN','TEST-NVL001','PENDING'),('BEP','DEMO-KITCHEN','TEST-NVL001','APPROVED'),('BEP','DEMO-KITCHEN','TEST-NVL001','REJECTED'),('PHA','DEMO-BARISTA','DEMO-TRA','PENDING'),('PHA','DEMO-BARISTA','DEMO-TRA','APPROVED'),('PHA','DEMO-BARISTA','DEMO-TRA','REJECTED')) v(prefix,actor,material,status) JOIN staff_users u ON u.code=v.actor JOIN materials m ON m.code=v.material JOIN material_lots l ON l.material_id=m.id JOIN material_balances mb ON mb.material_lot_id=l.id JOIN warehouse_locations w ON w.id=mb.location_id AND w.branch_id=u.branch_id ON CONFLICT (code) DO NOTHING;
INSERT INTO finished_goods_issues (code,branch_id,shift_code,status,note) SELECT 'DEMO-'||v.prefix||'-TP-'||(CASE v.status WHEN 'PENDING' THEN '001' WHEN 'APPROVED' THEN '002' ELSE '003' END),u.branch_id,s.id::text,v.status,'Lịch sử mẫu' FROM (VALUES ('BEP','DEMO-KITCHEN','PENDING'),('BEP','DEMO-KITCHEN','APPROVED'),('BEP','DEMO-KITCHEN','REJECTED'),('PHA','DEMO-BARISTA','PENDING'),('PHA','DEMO-BARISTA','APPROVED'),('PHA','DEMO-BARISTA','REJECTED')) v(prefix,actor,status) JOIN staff_users u ON u.code=v.actor JOIN staff_shifts s ON s.user_id=u.id AND s.ended_at IS NULL ON CONFLICT (code) DO NOTHING;
INSERT INTO finished_goods_issue_details (issue_id,product_code,requested_quantity,approved_quantity) SELECT i.id,CASE WHEN i.code LIKE 'DEMO-BEP-%' THEN 'DEMO-TP01' ELSE 'DEMO-DRINK01' END,2,CASE WHEN i.status='APPROVED' THEN 2 ELSE NULL END FROM finished_goods_issues i WHERE i.code LIKE 'DEMO-%-TP-%' ON CONFLICT (issue_id,product_code) DO NOTHING;
INSERT INTO staff_audits (id,actor_id,action,target_id,detail) SELECT gen_random_uuid(),u.id,'FINISHED_ISSUE_REQUEST',i.id::text,i.code FROM finished_goods_issues i JOIN staff_users u ON u.code=CASE WHEN i.code LIKE 'DEMO-BEP-%' THEN 'DEMO-KITCHEN' ELSE 'DEMO-BARISTA' END WHERE i.code LIKE 'DEMO-%-TP-%' AND NOT EXISTS (SELECT 1 FROM staff_audits a WHERE a.actor_id=u.id AND a.action='FINISHED_ISSUE_REQUEST' AND a.target_id=i.id::text);
INSERT INTO finished_goods_defects (code,branch_id,product_code,quantity,reason,deduct_from_stock,status) SELECT 'DEMO-'||v.prefix||'-LOI-'||(CASE v.status WHEN 'PENDING' THEN '001' WHEN 'APPROVED' THEN '002' ELSE '003' END),b.id,v.product,1,'Lịch sử mẫu: hình thức không đạt',true,v.status FROM (VALUES ('BEP','DEMO-TP01','PENDING'),('BEP','DEMO-TP01','APPROVED'),('BEP','DEMO-TP01','REJECTED'),('PHA','DEMO-DRINK01','PENDING'),('PHA','DEMO-DRINK01','APPROVED'),('PHA','DEMO-DRINK01','REJECTED')) v(prefix,product,status) CROSS JOIN branches b WHERE b.code='TEST-CN01' ON CONFLICT (code) DO NOTHING;
INSERT INTO staff_audits (id,actor_id,action,target_id,detail) SELECT gen_random_uuid(),u.id,'FINISHED_DEFECT_REQUEST',d.id::text,d.code FROM finished_goods_defects d JOIN staff_users u ON u.code=CASE WHEN d.code LIKE 'DEMO-BEP-%' THEN 'DEMO-KITCHEN' ELSE 'DEMO-BARISTA' END WHERE d.code LIKE 'DEMO-%-LOI-%' AND NOT EXISTS (SELECT 1 FROM staff_audits a WHERE a.actor_id=u.id AND a.action='FINISHED_DEFECT_REQUEST' AND a.target_id=d.id::text);
-- Hóa đơn mẫu cho thu ngân; không đặt lại các hóa đơn đã thao tác.
INSERT INTO restaurant_tables (id,branch_id,code,name,capacity) SELECT v.id::uuid,b.id,v.code,v.name,4 FROM (VALUES ('30000000-0000-4000-8000-000000000001','B01','Bàn 01'),('30000000-0000-4000-8000-000000000002','B02','Bàn 02')) v(id,code,name) CROSS JOIN branches b WHERE b.code='TEST-CN01' ON CONFLICT (branch_id,code) DO NOTHING;
INSERT INTO menu_items (id,branch_id,name,category,price) SELECT v.id::uuid,b.id,v.name,v.category,v.price FROM (VALUES ('30000000-0000-4000-8000-000000000011','Bò sốt cà chua','Món ăn',75000),('30000000-0000-4000-8000-000000000012','Trà sữa lài','Đồ uống',35000)) v(id,name,category,price) CROSS JOIN branches b WHERE b.code='TEST-CN01' ON CONFLICT (id) DO NOTHING;
INSERT INTO invoices (id,branch_id,table_id,guest_name,status) SELECT v.id::uuid,b.id,t.id,v.guest,v.status::"InvoiceStatus" FROM (VALUES ('30000000-0000-4000-8000-000000000021','B01','Khách bàn 01','OPEN'),('30000000-0000-4000-8000-000000000022','B02','Khách bàn 02','PAID')) v(id,table_code,guest,status) JOIN branches b ON b.code='TEST-CN01' JOIN restaurant_tables t ON t.branch_id=b.id AND t.code=v.table_code ON CONFLICT (id) DO NOTHING;
INSERT INTO staff_orders (id,invoice_id,created_by_id,request_key) SELECT v.id::uuid,v.invoice::uuid,u.id,v.id FROM (VALUES ('30000000-0000-4000-8000-000000000031','30000000-0000-4000-8000-000000000021'),('30000000-0000-4000-8000-000000000032','30000000-0000-4000-8000-000000000022')) v(id,invoice) JOIN staff_users u ON u.code='DEMO-CASHIER' ON CONFLICT (id) DO NOTHING;
INSERT INTO order_lines (id,order_id,menu_item_id,name,unit_price,quantity,status) SELECT v.id::uuid,v.order_id::uuid,m.id,m.name,m.price,v.quantity,v.status::"TicketStatus" FROM (VALUES ('30000000-0000-4000-8000-000000000041','30000000-0000-4000-8000-000000000031','30000000-0000-4000-8000-000000000011',2,'QUEUED'),('30000000-0000-4000-8000-000000000042','30000000-0000-4000-8000-000000000031','30000000-0000-4000-8000-000000000012',1,'READY'),('30000000-0000-4000-8000-000000000043','30000000-0000-4000-8000-000000000032','30000000-0000-4000-8000-000000000012',2,'SERVED')) v(id,order_id,menu,quantity,status) JOIN menu_items m ON m.id=v.menu::uuid ON CONFLICT (id) DO NOTHING;
INSERT INTO payments (id,invoice_id,cashier_id,amount,cash_received) SELECT '30000000-0000-4000-8000-000000000051', '30000000-0000-4000-8000-000000000022',id,70000,100000 FROM staff_users WHERE code='DEMO-CASHIER' ON CONFLICT (invoice_id) DO NOTHING;
